"""Generate model_sim_mp.py (80-digit, nudge-free Model M) from model_sim.py."""
import os

HERE = os.path.dirname(os.path.abspath(__file__))
src = open(os.path.join(HERE, "model_sim.py")).read()
rep = [
 ('"""\nmodel_sim.py -- Fast event-driven simulator for Model M (Section 2 dynamics).',
  '"""\nmodel_sim_mp.py -- model_sim.py at 80 significant digits, exact Model M.\n\n'
  'GENERATED by make_model_sim_mp.py; do not edit by hand. Same algorithm\n'
  'as model_sim.py, but all arithmetic in mpmath at mp.dps = 80, the model\n'
  'parameters as exact decimals, and no post-event separation nudge\n'
  '(EPS_SEP = 0), so it integrates Definition 2 itself rather than a\n'
  'perturbation of it.\n\nOriginal description:\n'
  'Fast event-driven simulator for Model M (Section 2 dynamics).'),
 ("import math\n",
  "from mpmath import mp\n\nmp.dps = 80\n\n\n"
  "class math:  # minimal shim so the float code runs unchanged in mp\n"
  "    sqrt = staticmethod(mp.sqrt)\n    hypot = staticmethod(mp.hypot)\n"
  "    acos = staticmethod(mp.acos)\n    cos = staticmethod(mp.cos)\n"
  "    sin = staticmethod(mp.sin)\n    pi = mp.pi\n\n"
  "    @staticmethod\n    def copysign(a, b):\n"
  "        return abs(a) if b >= 0 else -abs(a)\n"),
 ("L = 3.569", 'L = mp.mpf("3.569")'),
 ("W = 1.778", 'W = mp.mpf("1.778")'),
 ("R = 0.026250", 'R = mp.mpf("0.02625")'),
 ("A = 0.10", 'A = mp.mpf("0.10")'),
 ("E_BALL = 0.95", 'E_BALL = mp.mpf("0.95")'),
 ("E_CUSH = 0.90", 'E_CUSH = mp.mpf("0.90")'),
 ("RHO = 0.055", 'RHO = mp.mpf("0.055")'),
 ("EPS_SEP = 1e-9", "EPS_SEP = 0"),
 ("(1 / 3)", "(mp.mpf(1) / 3)"),
 ("for _ in range(80):", "for _ in range(400):"),
 ("if hi - lo < 1e-14:", "if hi - lo < mp.mpf('1e-75'):"),
 ("        self.x, self.y = x, y\n", "        self.x, self.y = mp.mpf(x), mp.mpf(y)\n"),
 ("POCKETS = ((0.0, 0.0), (L, 0.0), (0.0, W), (L, W), (L / 2, 0.0), (L / 2, W))",
  "POCKETS = ((0, 0), (L, 0), (0, W), (L, W), (L / 2, 0), (L / 2, W))"),
]
for a, b in rep:
    assert a in src, a
    src = src.replace(a, b)
open(os.path.join(HERE, "model_sim_mp.py"), "w").write(src)
print("wrote model_sim_mp.py")
